import fs from "fs";
import path from "path";
import type { NavigationBreakpoints } from "./types";
import { warnOnce } from "./util/warn";

export interface Breakpoints {
  mobile: string;
  desktop: string;
}

/** Quartz's own defaults from `quartz/styles/variables.scss`. */
export const defaultBreakpoints: Breakpoints = { mobile: "800px", desktop: "1200px" };

export const BREAKPOINTS_FILE = path.join("quartz", "styles", "variables.scss");
/**
 * Where QuartzControl, the predecessor of QuartzHub, keeps the breakpoints its frames switch at
 * (`{ "tablet": 1200, "mobile": 900 }`, pixels). A site laid out by such frames switches at these,
 * not at `variables.scss`.
 */
export const FRAME_BREAKPOINTS_FILE = path.join(".quartz-gui", "layout-breakpoints.json");

export const MOBILE_PLACEHOLDER = "__NAV_BP_MOBILE__";
export const DESKTOP_PLACEHOLDER = "__NAV_BP_DESKTOP__";

/** Reads `$breakpoints: (mobile: 800px, desktop: 1200px)` from the contents of `variables.scss`. */
export function parseBreakpoints(scss: string): Partial<Breakpoints> {
  const map = /\$breakpoints\s*:\s*\(([^)]*)\)/.exec(scss);
  if (!map) return {};
  const out: Partial<Breakpoints> = {};
  for (const entry of map[1]!.split(",")) {
    const m = /^\s*(mobile|desktop)\s*:\s*([0-9.]+(?:px|rem|em))\s*$/.exec(entry);
    if (m) out[m[1] as keyof Breakpoints] = m[2]!;
  }
  return out;
}

/**
 * Quartz 5 has no configuration option for breakpoints; sites change them in
 * `quartz/styles/variables.scss`. The plugin runs inside the site's build, so the file is read
 * relative to the working directory.
 */
export function readProjectBreakpoints(cwd = process.cwd()): Partial<Breakpoints> | undefined {
  const file = path.join(cwd, BREAKPOINTS_FILE);
  try {
    if (!fs.existsSync(file)) return undefined;
    return parseBreakpoints(fs.readFileSync(file, "utf8"));
  } catch {
    return undefined;
  }
}

/**
 * Reads the frame breakpoints (QuartzControl, now QuartzHub). `mobile` is the width up to which the frame shows its
 * mobile layout, `tablet` the one up to which it shows the tablet layout, which is what Quartz
 * calls the desktop breakpoint.
 */
export function parseFrameBreakpoints(json: string): Partial<Breakpoints> {
  let data: unknown;
  try {
    data = JSON.parse(json);
  } catch {
    return {};
  }
  if (data === null || typeof data !== "object") return {};
  const record = data as Record<string, unknown>;
  const out: Partial<Breakpoints> = {};
  const mobile = validLength(record.mobile);
  const desktop = validLength(record.tablet);
  if (mobile) out.mobile = mobile;
  if (desktop) out.desktop = desktop;
  return out;
}

export function readFrameBreakpoints(cwd = process.cwd()): Partial<Breakpoints> | undefined {
  const file = path.join(cwd, FRAME_BREAKPOINTS_FILE);
  try {
    if (!fs.existsSync(file)) return undefined;
    return parseFrameBreakpoints(fs.readFileSync(file, "utf8"));
  } catch {
    return undefined;
  }
}

/** A positive length: a breakpoint of 0 would switch nothing. */
function validLength(value: unknown): string | undefined {
  if (typeof value === "number" && Number.isFinite(value) && value > 0) return `${value}px`;
  if (typeof value === "string" && /^[0-9.]+(px|rem|em)$/.test(value.trim())) {
    return parseFloat(value) > 0 ? value.trim() : undefined;
  }
  return undefined;
}

/**
 * The option wins, then the frame breakpoints (`.quartz-gui/layout-breakpoints.json`), then `variables.scss`,
 * then Quartz's defaults. The frame comes first because it is what actually switches the page
 * layout: the navigation should change its presentation at the same width.
 */
export function resolveBreakpoints(
  override: NavigationBreakpoints | undefined,
  cwd = process.cwd(),
): Breakpoints {
  const frame = readFrameBreakpoints(cwd);
  const project = readProjectBreakpoints(cwd);
  // A frame file without usable values counts as no file.
  const hasFrame = frame !== undefined && Object.keys(frame).length > 0;
  if (!project && !hasFrame) {
    warnOnce(
      "breakpoints-file",
      `Could not read ${BREAKPOINTS_FILE}; using ${defaultBreakpoints.mobile} / ${defaultBreakpoints.desktop} as breakpoints.`,
    );
  }
  return {
    mobile:
      validLength(override?.mobile) ??
      frame?.mobile ??
      project?.mobile ??
      defaultBreakpoints.mobile,
    desktop:
      validLength(override?.desktop) ??
      frame?.desktop ??
      project?.desktop ??
      defaultBreakpoints.desktop,
  };
}

/** Replaces the placeholders the stylesheet uses in its media queries. */
export function applyBreakpoints(css: string, bp: Breakpoints): string {
  return css.split(MOBILE_PLACEHOLDER).join(bp.mobile).split(DESKTOP_PLACEHOLDER).join(bp.desktop);
}
